c = Company.find(4)
import_note = "Imported from Facebook Leads CSV (3/19/2026)"
dup_count = 0
puts "SKIPPED DUPLICATES (already existed before this import):"
puts "Name | Email | Source | Original Created Date"
puts "-" * 80
all_emails.each do |e|
  lead = c.leads.where(email: e).where.not(notes: import_note).first
